package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public class Procedure079Test {
 static JSONObject protocol()throws Exception{try(var in=Procedure079.class.getResourceAsStream("/procedures079-protocol.json")){return new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}}
 private JSONObject candidate(String family,double saving,double distance){return new JSONObject().put("id","owned").put("family",family).put("distance",distance).put("lowerSavingMillis",saving);}
 @Test public void skipsCostlyDistantAndDirectExperience(){for(var c:List.of(candidate("two-stage",-1,.01),candidate("two-stage",100,.11),candidate("direct",100,.01)))assertFalse(Procedure079.choose(new JSONObject(),"adaptive",new JSONArray().put(c)).getBoolean("useMemory"));}
 @Test public void positiveBoundedBenefitChangesOnlyOrder(){var d=Procedure079.choose(new JSONObject(),"adaptive",new JSONArray().put(candidate("clear-two",1,.1)));assertTrue(d.getBoolean("useMemory"));assertEquals("clear-two",Procedure079.order(d).get(0));assertEquals(new HashSet<>(Procedure078.FAMILIES),new HashSet<>(Procedure079.order(d)));}
 @Test public void simpleAndEmptyFallbackHaveNoMemoryAuthority(){assertFalse(Procedure079.choose(new JSONObject(),"simple",new JSONArray()).getBoolean("useMemory"));assertFalse(Procedure079.choose(new JSONObject(),"memory",new JSONArray()).getBoolean("useMemory"));assertThrows(IllegalArgumentException.class,()->Procedure079.choose(new JSONObject(),"claimed-success",new JSONArray()));}
 @Test public void closestCandidateControlsSelectionNotOptimisticDistantOne(){var xs=new JSONArray().put(candidate("clear-two",10000,.2)).put(candidate("direct",0,.01));assertFalse(Procedure079.choose(new JSONObject(),"adaptive",xs).getBoolean("useMemory"));assertEquals("direct",Procedure079.choose(new JSONObject(),"memory",xs).getString("preferred"));}
 @Test public void coldProofCostAndUncertaintyAreCharged()throws Exception{var s=protocol().getJSONArray("training").getJSONObject(0);var b=new JSONObject().put("id","owned").put("family","two-stage").put("spec",s).put("activeMillis",10000).put("auditMillis",2000).put("avoidedMillis",1200);assertEquals(450,Procedure079.estimate(b,s,true).getDouble("lowerSavingMillis"),1e-6);assertEquals(-1300,Procedure079.estimate(b,s,false).getDouble("lowerSavingMillis"),1e-6);}
 @Test public void retainedKindRoutesToCurrentWorld(){assertEquals("world",Domain044.familyFor(Procedure079.KIND));}
 @Test public void currentFrameAndUnitsDriveWaypoints()throws Exception{var s=protocol().getJSONArray("training").getJSONObject(0);var raw=WorldFrames.copy(s.getJSONObject("source"));raw.put("units","cm");for(Object x:raw.getJSONArray("objects")){var o=(JSONObject)x;for(String key:List.of("position","size"))for(int k=0;k<3;k++)o.getJSONArray(key).put(k,o.getJSONArray(key).getDouble(k)*100);}for(String key:List.of("a","b"))for(int k=0;k<3;k++)raw.getJSONObject("scaleReference").getJSONArray(key).put(k,raw.getJSONObject("scaleReference").getJSONArray(key).getDouble(k)*100);var frame=WorldFrames.initial(SpatialScene.parse(raw.toString(),UUID.randomUUID().toString()));var b=frame.getJSONArray("bodies").getJSONObject(0);b.getJSONArray("position").put(0,b.getJSONArray("position").getDouble(0)+.2);frame.put("elapsedTicks",123);var spec=Procedure079.spec(frame,s);var rebased=Procedure078.scene(spec);assertEquals(b.getJSONArray("position").getDouble(0),rebased.getJSONArray("objects").getJSONObject(1).getJSONArray("position").getDouble(0),1e-8);var choice=Waypoints079.choose(spec,"direct",0,frame,frame);assertTrue(choice.getJSONObject("plan").getBoolean("passed"));}
}
